from pathlib import Path
import hashlib,json,os,shutil,zipfile,io,base64,subprocess
B=Path('/opt/alice-market/releases/alisa-accrual-day-speech-r1-20261114')
C=Path('/opt/alice-market/candidates/alisa-accrual-price-extrema-20261114')
T=Path('/opt/alice-market/candidates/accrual-price-extrema-tests-20261114')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
assert Path('/opt/alice-market/releases/current').resolve()==B
assert sha(B/'manifest.json')=='af5fdc23472211d235770472703372e767bee7c77fee0a0c940a3cddd1b8c5c0'
m=json.loads((B/'manifest.json').read_text())
for n,h in m['files'].items():assert sha(B/n)==h,n
assert not C.exists()and not T.exists()
shutil.copytree(B,C,copy_function=os.link,ignore=shutil.ignore_patterns('__pycache__'))
T.mkdir(mode=0o755)
Z=zipfile.ZipFile(io.BytesIO(base64.b64decode('')))
assert set(Z.namelist())=={'template_catalog.json','test_accrual_cardinality_context.py'}
(C/'template_catalog.json').unlink();(C/'template_catalog.json').write_bytes(Z.read('template_catalog.json'))
(T/'test_accrual_cardinality_context.py').write_bytes(Z.read('test_accrual_cardinality_context.py'))
assert sha(C/'template_catalog.json')=='6177f187e7c2fb63fc97acd5debaae3b6d7f4189c1aebef62d8271bcf6574901'
assert sha(T/'test_accrual_cardinality_context.py')=='8dfbd8b45bd936f8e760cf92f8b96d4d743887eb9b6d89b460a08bc145a8b6cc'
with (T/'focused-final.log').open('w')as f:
 result=subprocess.run(['runuser','-u','alice-lab','--','env','PYTHONDONTWRITEBYTECODE=1','PYTHONPATH='+str(C)+':'+str(C/'tests')+':'+str(T)+':/opt/alice-market/candidates/dataset-selector-metadata-tests-20261113','/usr/bin/python3','-B','-m','unittest','test_accrual_cardinality_context','test_template_only','test_template_integration','test_selector_prefix_cache','test_template_clarification_extension','test_dataset_selector_metadata','-q'],stdout=f,stderr=subprocess.STDOUT,timeout=150)
print((T/'focused-final.log').read_text()[-700:])
assert result.returncode==0
assert 'Ran 147 tests'in (T/'focused-final.log').read_text()
print(json.dumps({'status':'PASS','tests':147,'catalog_sha256':sha(C/'template_catalog.json'),'base_payload_files':len(m['files']),'only_changed':[n for n,h in m['files'].items()if sha(C/n)!=h]}))
